"""Install a Git pre-commit hook that runs verify_qm_atlas_loc.py and test_qm_atlas_loc.py
whenever Lean (.lean), Rust (.rs), Python (.py), or manuscript (.md) files are edited.
"""
from __future__ import annotations

from pathlib import Path
import stat

REPO_ROOT = Path(__file__).resolve().parents[1]
HOOK_PATH = REPO_ROOT / ".git" / "hooks" / "pre-commit"

HOOK_SCRIPT = """#!/bin/sh
# Auto-generated by scripts/install_qm_atlas_hook.py
# Runs QM Atlas LOC and symbol synchronization checks whenever .lean, .rs, .py, or .md files are staged.

CHANGED=$(git diff --cached --name-only --diff-filter=ACMR | grep -E '\\.(lean|rs|py|md)$' || true)
if [ -n "$CHANGED" ]; then
    echo "[qm-atlas-sync] Detected edits to Lean/Rust/Python/Markdown files; verifying QM Atlas LOC & symbol bindings..."
    python scripts/verify_qm_atlas_loc.py || exit 1
    python -m pytest code/python/tests/test_qm_atlas_loc.py -q || exit 1
fi
exit 0
"""


def install_pre_commit_hook(repo_root: Path = REPO_ROOT) -> Path:
    hook_path = repo_root / ".git" / "hooks" / "pre-commit"
    hook_path.parent.mkdir(parents=True, exist_ok=True)
    hook_path.write_text(HOOK_SCRIPT, encoding="utf-8", newline="\n")
    current_mode = hook_path.stat().st_mode
    hook_path.chmod(current_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    return hook_path


def main() -> int:
    path = install_pre_commit_hook()
    print(f"Installed QM Atlas pre-commit hook at: {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
